constraints:
1 <= N <= 10^{5}
1 <= arr[i] <= 10^{5}

expected time complexity: O(N)
expected auxiliary space: O(1)

standard_solution_code:
class Solution:

	def sumBitDifferences(self, arr, n):
		n = len(arr)
		sum_bit_diff = 0
		for i in range(32):
			count_set_bits = 0
			count_clear_bits = 0
			for j in range(n):
				if arr[j] & 1 << i:
					count_set_bits += 1
				else:
					count_clear_bits += 1
			sum_bit_diff += count_set_bits * count_clear_bits * 2
		return sum_bit_diff
